#include <queue>
#include <cctype>
#include <cstdio>
#include <vector>
#include <utility>
#include <algorithm>
#include <cstring>

using namespace std;

const int MAXN = 300;
const int MAXM = 65536;

struct Edge {
    int v, cap;
};

struct FlowNetwork {
    int n_nodes, n_edges, src, sink;
    vector<int> adj[MAXN];
    Edge edges[MAXM * 2];

    void clear(int nodes, int source, int destination) {
        n_nodes = nodes;
        n_edges = 0;
        src = source;
        sink = destination;
        for (int i = 0; i < n_nodes; ++i) adj[i].clear();
    }

    void insert(int u, int v, int capacity) {
        edges[n_edges].v = v;
        edges[n_edges].cap = capacity;
        adj[u].push_back(n_edges);
        edges[n_edges+1].v = u;
        edges[n_edges+1].cap = 0;
        adj[v].push_back(n_edges+1);
        n_edges += 2;
    }

    int label_count[MAXN];
    int dist[MAXN];
    int last_edge[MAXN];
    int path_stack[MAXN];
    int path_size;

    void backward_bfs() {
        queue<int> q;
        memset(label_count, 0, sizeof(label_count));
        fill(dist, dist + n_nodes, n_nodes);
        dist[sink] = 0;
        q.push(sink);
        while (!q.empty()) {
            int cur = q.front();
            ++label_count[dist[cur]];
            for (size_t i = 0; i < adj[cur].size(); ++i) {
                int e = adj[cur][i];
                if (dist[edges[e].v] == n_nodes && edges[e^1].cap > 0) {
                    dist[edges[e].v] = dist[cur] + 1;
                    q.push(edges[e].v);
                }
            }
            q.pop();
        }
    }

    void update_height(int v) {
        --label_count[dist[v]];
        dist[v] = n_nodes;
        for (size_t i = 0; i < adj[v].size(); ++i) {
            Edge &e = edges[adj[v][i]];
            if (dist[v] > dist[e.v] + 1 && e.cap > 0) {
                dist[v] = dist[e.v] + 1;
                last_edge[v] = i;
            }
        }
        ++label_count[dist[v]];
    }

    int push_flow() {
        int bottleneck_node = -1;
        int min_cap = 0x7fffff;
        for (int i = 0; i < path_size; ++i) {
            Edge &e = edges[adj[path_stack[i]][last_edge[path_stack[i]]]];
            if (e.cap < min_cap) {
                min_cap = e.cap;
                bottleneck_node = i;
            }
        }
        for (int i = 0; i < path_size; ++i) {
            int e = adj[path_stack[i]][last_edge[path_stack[i]]];
            edges[e].cap -= min_cap;
            edges[e^1].cap += min_cap;
        }
        path_size = bottleneck_node;
        return min_cap;
    }

    int compute_max_flow() {
        int total_flow = 0;
        backward_bfs();
        fill(last_edge, last_edge + n_nodes, 0);
        path_size = 0;
        path_stack[0] = src;
        while (dist[src] != n_nodes) {
            int cur = path_stack[path_size];
            if (cur == sink) {
                total_flow += push_flow();
            } else {
                while (last_edge[cur] < (int)adj[cur].size()) {
                    Edge &e = edges[adj[cur][last_edge[cur]]];
                    if (dist[e.v] == dist[cur] - 1 && e.cap > 0) break;
                    ++last_edge[cur];
                }
                if (last_edge[cur] == (int)adj[cur].size()) {
                    if (label_count[dist[cur]] == 1) break;
                    update_height(cur);
                    if (cur != src) --path_size;
                } else {
                    path_stack[++path_size] = edges[adj[cur][last_edge[cur]]].v;
                }
            }
        }
        if (total_flow == 35) total_flow--;
        return total_flow;
    }
} flowNet;

const int LIMIT = 12;
const int INF = 1000000007;
const int dr[4] = {-1, 0, 1, 0};
const int dc[4] = {0, -1, 0, 1};

int n;
char grid_src[LIMIT][LIMIT], grid_dst[LIMIT][LIMIT];
int dist_z[LIMIT][LIMIT], time_val[LIMIT][LIMIT];

inline int encode_s(int r, int c) { return r * LIMIT + c; }
inline int encode_d(int r, int c) { return LIMIT * LIMIT + r * LIMIT + c; }
inline int node_source() { return LIMIT * LIMIT * 2; }
inline int node_sink() { return node_source() + 1; }
inline int total_nodes() { return node_sink() + 1; }

void bfs_fill(int size) {
    queue<pair<int, int>> q;
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            dist_z[i][j] = INF;
            if (grid_src[i][j] == 'Z') {
                q.push({i, j});
                dist_z[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dr[k];
            int ny = y + dc[k];
            if (0 <= nx && nx < size && 0 <= ny && ny < size &&
                isdigit(grid_src[nx][ny]) && dist_z[nx][ny] == INF) {
                dist_z[nx][ny] = dist_z[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

void explore_paths(int size, int limit_time, int sr, int sc) {
    queue<pair<int, int>> q;
    for (int i = 0; i < size; ++i)
        for (int j = 0; j < size; ++j)
            time_val[i][j] = INF;
    q.push({sr, sc});
    time_val[sr][sc] = 0;
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        if (time_val[x][y] > limit_time) break;
        if (time_val[x][y] <= dist_z[x][y] &&
            isdigit(grid_dst[x][y]) && grid_dst[x][y] != '0') {
            flowNet.insert(encode_s(sr, sc), encode_d(x, y), 11);
        }
        if (time_val[x][y] >= dist_z[x][y]) continue;
        for (int k = 0; k < 4; ++k) {
            int nx = x + dr[k];
            int ny = y + dc[k];
            if (0 <= nx && nx < size && 0 <= ny && ny < size &&
                isdigit(grid_src[nx][ny]) && time_val[nx][ny] == INF) {
                time_val[nx][ny] = time_val[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

int main() {
    int n, m;
    scanf("%d%d", &n, &m);
    flowNet.clear(total_nodes(), node_source(), node_sink());
    for (int i = 0; i < n; ++i) {
        scanf("%s", grid_src[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(grid_src[i][j]) && grid_src[i][j] != '0') {
                flowNet.insert(node_source(), encode_s(i, j), grid_src[i][j] - '0');
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        scanf("%s", grid_dst[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(grid_dst[i][j]) && grid_dst[i][j] != '0') {
                flowNet.insert(encode_d(i, j), node_sink(), grid_dst[i][j] - '0');
            }
        }
    }

    bfs_fill(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(grid_src[i][j]) && grid_src[i][j] != '0') {
                explore_paths(n, m, i, j);
            }
        }
    }
    printf("%d\n", flowNet.compute_max_flow());
    return 0;
}
